package com.campusmart.controller;
import com.campusmart.dto.OrderDtos; import com.campusmart.entity.Order; import com.campusmart.service.OrderService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService s;public OrderController(OrderService s){this.s=s;}@PostMapping public Order create(@Valid @RequestBody OrderDtos.Create d,Authentication a){return s.create(d,Long.valueOf(a.getName()));}@GetMapping public List<Order> mine(Authentication a){return s.mine(Long.valueOf(a.getName()));}@GetMapping("/{id}") public Order get(@PathVariable Long id,Authentication a){Order o=s.get(id);if(!o.getBuyer().getId().equals(Long.valueOf(a.getName()))&&!a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")))throw new IllegalArgumentException("Forbidden");return o;}}
